import { ENDPOINTS } from '../../config/api';

export async function postActorVoz(data) {
	const response = await fetch(ENDPOINTS.actorVoz.create, {
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify(data),
	});
	if (!response.ok) throw new Error('Error al crear el actor de voz');
	return response.json();
}

export async function getActoresVoz() {
	const response = await fetch(ENDPOINTS.actorVoz.getAll);
	if (!response.ok) throw new Error('Error al obtener actores de voz');
	return response.json();
}

export async function getActorVozById(id) {
	const response = await fetch(ENDPOINTS.actorVoz.getById.replace('{id}', String(id)));
	if (!response.ok) throw new Error('Error al obtener el actor de voz');
	return response.json();
}

export async function putActorVoz(id, data) {
	const response = await fetch(ENDPOINTS.actorVoz.update, {
		method: 'PUT',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify({ id, ...data })
	});
	if (!response.ok) throw new Error('Error al actualizar el actor de voz');
	return response.json();
}

export async function deleteActorVoz(id) {
	const response = await fetch(ENDPOINTS.actorVoz.delete.replace('{id}', String(id)), {
		method: 'DELETE'
	});
	if (!response.ok) throw new Error('Error al eliminar el actor de voz');
}

export async function deleteLogicalActorVoz(id) {
	const response = await fetch(ENDPOINTS.actorVoz.deleteLogical.replace('{id}', String(id)), {
		method: 'DELETE'
	});
	if (!response.ok) throw new Error('Error al eliminar lógicamente el actor de voz');
}

