import { ENDPOINTS } from '../../config/api';
/**
 * Creates a new form in the system.
 * @param data - Data of the form to create
 * @returns Promise with the API response
 */
export async function postForm(data) {
	const response = await fetch(ENDPOINTS.form.create, {
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify(data),
	});
	if (!response.ok) throw new Error('Error al crear el formulario');
	return response.json();
}


/**
 * Gets the list of all forms.
 * @returns Promise with the array of forms
 */
export async function getForms() {
	const response = await fetch(ENDPOINTS.form.getAll);
	if (!response.ok) throw new Error('Error al obtener formularios');
	return response.json();
}

/**
 * Gets a form by its ID.
 * @param id - Form ID
 * @returns Promise with the form
 */
export async function getFormById(id) {
	const response = await fetch(ENDPOINTS.form.getById.replace('{id}', String(id)));
	if (!response.ok) throw new Error('Error al obtener el formulario');
	return response.json();
}

/**
 * Updates a form by its ID.
 * @param id - Form ID
 * @param data - Updated form data
 * @returns Promise with the API response
 */
export async function putForm(id, data) {
	const response = await fetch(ENDPOINTS.form.update, {
		method: 'PUT',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify({ id, ...data })
	});
	if (!response.ok) throw new Error('Error al actualizar el formulario');
	return response.json();
}

/**
 * Deletes a form by its ID.
 * @param id - Form ID
 */
export async function deleteForm(id) {
	const response = await fetch(ENDPOINTS.form.delete.replace('{id}', String(id)), {
		method: 'DELETE'
	});
	if (!response.ok) throw new Error('Error al eliminar el formulario');
}

