import { Star, Calendar, Play } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Anime } from '@/Api/types';
import { cn } from '@/lib/utils';

interface AnimeCardProps {
  anime: Anime;
  onClick?: () => void;
}

export const AnimeCard = ({ anime, onClick }: AnimeCardProps) => {
  return (
    <Card 
      className="group relative overflow-hidden border-border bg-card transition-all duration-300 hover:shadow-card-hover hover:scale-[1.02] cursor-pointer"
      onClick={onClick}
    >
      {/* Image placeholder */}
      <div className="relative aspect-[3/4] overflow-hidden bg-gradient-primary">
        <div className="absolute inset-0 flex items-center justify-center">
          <Play className="h-16 w-16 text-white/50" />
        </div>
        <div className="absolute inset-0 bg-gradient-to-t from-background via-transparent to-transparent opacity-60" />
      </div>

      {/* Content */}
      <div className="p-4 space-y-3">
        <div>
          <h3 className="font-bold text-lg text-foreground line-clamp-1 group-hover:text-primary transition-colors">
            {anime.Titulo}
          </h3>
          <p className="text-sm text-muted-foreground line-clamp-2 mt-1">
            {anime.Sinopsis || 'Sin sinopsis disponible'}
          </p>
        </div>

        {/* Studio & Date */}
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Calendar className="h-3.5 w-3.5" />
          <span>{anime.FechaEmision ? new Date(anime.FechaEmision).getFullYear() : 'N/A'}</span>
          {anime.Studio && (
            <>
              <span>•</span>
              <span className="truncate">{anime.Studio.Nombre}</span>
            </>
          )}
        </div>

        {/* Genres */}
        {anime.Genres && anime.Genres.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {anime.Genres.slice(0, 3).map((genre) => (
              <Badge key={genre.Id} variant="secondary" className="text-xs px-2 py-0.5">
                {genre.Nombre}
              </Badge>
            ))}
          </div>
        )}

        {/* Status Badge */}
        <Badge 
          variant={anime.Estado === 'En emisión' ? 'default' : 'outline'}
          className={cn(
            "absolute top-3 right-3",
            anime.Estado === 'En emisión' && "bg-gradient-accent"
          )}
        >
          {anime.Estado || 'Desconocido'}
        </Badge>
      </div>
    </Card>
  );
};

