import { Card } from '@/components/ui/card';
import { LucideIcon } from 'lucide-react';
import { cn } from '@/lib/utils';

interface StatCardProps {
  title: string;
  value: string | number;
  icon: LucideIcon;
  trend?: {
    value: number;
    isPositive: boolean;
  };
  gradient?: 'primary' | 'accent' | 'secondary';
}

export const StatCard = ({ title, value, icon: Icon, trend, gradient = 'primary' }: StatCardProps) => {
  const gradientClasses = {
    primary: 'bg-gradient-primary',
    accent: 'bg-gradient-accent',
    secondary: 'bg-gradient-secondary',
  };

  return (
    <Card className="relative overflow-hidden border-border bg-card p-6 transition-all duration-300 hover:shadow-card-hover">
      <div className="flex items-start justify-between">
        <div className="space-y-2">
          <p className="text-sm font-medium text-muted-foreground">{title}</p>
          <p className="text-3xl font-bold text-foreground">{value}</p>
          {trend && (
            <div className={cn(
              "flex items-center gap-1 text-sm font-medium",
              trend.isPositive ? "text-secondary" : "text-destructive"
            )}>
              <span>{trend.isPositive ? '↑' : '↓'}</span>
              <span>{Math.abs(trend.value)}%</span>
            </div>
          )}
        </div>
        <div className={cn(
          "flex h-12 w-12 items-center justify-center rounded-lg",
          gradientClasses[gradient]
        )}>
          <Icon className="h-6 w-6 text-white" />
        </div>
      </div>
      <div className={cn(
        "absolute -bottom-6 -right-6 h-24 w-24 rounded-full opacity-10",
        gradientClasses[gradient]
      )} />
    </Card>
  );
};

