@tailwind base;
@tailwind components;
@tailwind utilities;

/* Definition of the design system. All colors, gradients, fonts, etc should be defined here. 
All colors MUST be HSL.
*/

@layer base {
  :root {
    --background: 240 10% 3.9%;
    --foreground: 0 0% 98%;

    --card: 240 10% 8%;
    --card-foreground: 0 0% 98%;

    --popover: 240 10% 6%;
    --popover-foreground: 0 0% 98%;

    --primary: 263 70% 50%;
    --primary-foreground: 0 0% 100%;

    --secondary: 217 91% 60%;
    --secondary-foreground: 0 0% 100%;

    --muted: 240 5% 15%;
    --muted-foreground: 240 5% 65%;

    --accent: 330 81% 60%;
    --accent-foreground: 0 0% 100%;

    --warning: 38 92% 50%;
    --warning-foreground: 0 0% 100%;

    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 98%;

    --border: 240 5% 18%;
    --input: 240 6% 14%;
    --ring: 263 70% 50%;

    --radius: 0.75rem;

    --gradient-primary: linear-gradient(135deg, hsl(263 70% 50%), hsl(280 70% 60%));
    --gradient-accent: linear-gradient(135deg, hsl(330 81% 60%), hsl(340 85% 65%));
    --gradient-secondary: linear-gradient(135deg, hsl(217 91% 60%), hsl(200 90% 55%));
    --gradient-hero: linear-gradient(135deg, hsl(263 70% 20%), hsl(240 10% 3.9%));

    --sidebar-background: 240 10% 5%;
