pages.Animes.tsx:
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Search, Plus, Filter } from 'lucide-react';
import { DashboardLayout } from '@/layout/DashboardLayout';
import { AnimeCard } from '@/components/AnimeCard';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { animeService } from '@/Api/Services/anime/animeService';
import { Skeleton } from '@/components/ui/skeleton';

const Animes = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const { data: animes, isLoading } = useQuery({
    queryKey: ['animes'],
    queryFn: animeService.getAll,
  });

  const filteredAnimes = animes?.filter((anime) =>
    anime.Titulo.toLowerCase().includes(searchQuery.toLowerCase()) ||
    anime.Sinopsis?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <DashboardLayout>
      <div className="space-y-8">
        {/* Header */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-4xl font-bold text-foreground mb-2">Catálogo de Animes</h1>
            <p className="text-muted-foreground">Explora y gestiona toda la colección de animes</p>
          </div>
          <Button className="bg-gradient-primary hover:opacity-90 transition-opacity">
            <Plus className="mr-2 h-4 w-4" />
            Agregar Anime
          </Button>
        </div>

        {/* Search and Filter Bar */}
        <div className="flex flex-col gap-4 sm:flex-row">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Buscar animes por título o sinopsis..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
            />
          </div>
          <Button variant="outline" className="gap-2">
            <Filter className="h-4 w-4" />
            Filtros
          </Button>
        </div>

        {/* Anime Grid */}
        {isLoading ? (
          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
            {[...Array(8)].map((_, i) => (
              <div key={i} className="space-y-3">
                <Skeleton className="aspect-[3/4] w-full rounded-lg" />
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="h-3 w-full" />
              </div>
            ))}
          </div>
        ) : filteredAnimes && filteredAnimes.length > 0 ? (
          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
            {filteredAnimes.map((anime) => (
              <AnimeCard key={anime.Id} anime={anime} />
            ))}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="rounded-full bg-muted p-6 mb-4">
              <Search className="h-12 w-12 text-muted-foreground" />
            </div>
            <h3 className="text-xl font-semibold text-foreground mb-2">No se encontraron animes</h3>
            <p className="text-muted-foreground max-w-md">
              {searchQuery
                ? 'Intenta con otros términos de búsqueda'
                : 'Comienza agregando tu primer anime al catálogo'}
            </p>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
};

export default Animes;

pages.Dashboard.tsx:
import { useQuery } from '@tanstack/react-query';
import { Library, Users, Film, Award, TrendingUp } from 'lucide-react';
import { DashboardLayout } from '@/layout/DashboardLayout';
import { StatCard } from '@/components/StatCard';
import { AnimeCard } from '@/components/AnimeCard';
import { animeService } from '@/Api/Services/anime/animeService';
import { Skeleton } from '@/components/ui/skeleton';

const Dashboard = () => {
  const { data: animes, isLoading } = useQuery({
    queryKey: ['animes'],
    queryFn: animeService.getAll,
  });

  const stats = [
    { title: 'Total Animes', value: animes?.length || 0, icon: Library, trend: { value: 12, isPositive: true }, gradient: 'primary' as const },
    { title: 'Usuarios Activos', value: '1,234', icon: Users, trend: { value: 8, isPositive: true }, gradient: 'accent' as const },
    { title: 'Estudios', value: '45', icon: Film, trend: { value: 3, isPositive: true }, gradient: 'secondary' as const },
    { title: 'Géneros', value: '28', icon: Award, gradient: 'primary' as const },
  ];

  return (
    <DashboardLayout>
      <div className="space-y-8">
        {/* Header */}
        <div>
          <h1 className="text-4xl font-bold text-foreground mb-2">Dashboard</h1>
          <p className="text-muted-foreground">Bienvenido al panel de administración de AnimeHub</p>
        </div>

        {/* Stats Grid */}
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
          {stats.map((stat, index) => (
            <StatCard key={index} {...stat} />
          ))}
        </div>

        {/* Recent Animes */}
        <div>
          <div className="flex items-center justify-between mb-6">
            <div>
              <h2 className="text-2xl font-bold text-foreground">Animes Recientes</h2>
              <p className="text-sm text-muted-foreground mt-1">Los últimos animes agregados al catálogo</p>
            </div>
            <TrendingUp className="h-6 w-6 text-primary" />
          </div>

          {isLoading ? (
            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="space-y-3">
                  <Skeleton className="aspect-[3/4] w-full rounded-lg" />
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-full" />
                </div>
              ))}
            </div>
          ) : (
            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {animes?.slice(0, 4).map((anime) => (
                <AnimeCard key={anime.Id} anime={anime} />
              ))}
            </div>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
};

export default Dashboard;

